// Vault and workspace management tools. Secret values never pass through the
// model: they are read from local files or generated by opsdeck, stored
// directly, and from then on redacted from everything the model sees.

func vaultScope(env *Env, scope string) (string, error) {
	switch scope {
	case "", "workspace", env.WS.Name():
		return env.WS.Name(), nil
	case vault.GlobalScope:
		return vault.GlobalScope, nil
	}
	return "", fmt.Errorf("scope must be \"workspace\" (%s) or %q", env.WS.Name(), vault.GlobalScope)
}

var itemNameRe = strings.NewReplacer(" ", "-", "_", "-", ".", "-")

// itemName derives a vault item name from a file name (id_ed25519 -> id-ed25519).
func itemName(s string) string {
	s = strings.ToLower(itemNameRe.Replace(strings.TrimSpace(s)))
	return strings.Trim(slugRe.ReplaceAllString(s, "-"), "-")
}

func agentNote(what string) string {
	return what + " by the opsdeck agent on " + time.Now().Format("2006-01-02 15:04")
}

func toolVaultList() Tool {
	return Tool{
		Def: llm.Tool{Name: "vault_list", Description: "List the vault items this workspace can use (its own scope and the global scope): reference, type, whether the agent may use it, and non-secret fields such as usernames, URLs and SSH public keys. Secret values are never shown. Use the vault:// references in resources (e.g. a Host's auth).",
			Schema: obj(map[string]any{
				"scope": enum("Which scope (default both)", "workspace", "global", "all"),
				"query": str("Optional text to match in name, type or tags"),
			})},
		Prepare: func(ctx context.Context, env *Env, input json.RawMessage) (*Call, error) {
			var in struct{ Scope, Query string }
			if err := decode(input, &in); err != nil {
				return nil, err
			}
			return &Call{Risk: RiskRead, Target: "vault", Run: func(ctx context.Context) (string, error) {
				var scopes []string
				switch in.Scope {
				case "workspace":
					scopes = []string{env.WS.Name()}
				case "global":
					scopes = []string{vault.GlobalScope}
				default:
					scopes = []string{env.WS.Name(), vault.GlobalScope}
				}
				var b strings.Builder
				q := strings.ToLower(in.Query)
				n := 0
				for _, sc := range scopes {
					items, err := env.Vault.List(sc)
					if err != nil {
						return "", err
					}
					for _, it := range items {
						hay := strings.ToLower(it.Name + " " + it.Type + " " + strings.Join(it.Tags, " "))
						if q != "" && !strings.Contains(hay, q) {
							continue
						}
						n++
						use := "agent may use"
						if !it.Policy.AgentUse {
							use = "NOT allowed for agent use"
						}
						if it.Policy.ConfirmOnUse {
							use += ", confirm on every use"
						}
						fmt.Fprintf(&b, "- %s (%s; %s)", it.Ref(), it.Type, use)
						if len(it.Tags) > 0 {
							fmt.Fprintf(&b, " tags: %s", strings.Join(it.Tags, ", "))
						}
						b.WriteString("\n")
						var secrets []string
						for _, f := range it.Fields {
							switch {
							case f.Secret:
								secrets = append(secrets, f.Name)
							case f.Value != "":
								v := f.Value
								if f.Name == "public_key" {
									if pk, _, _, _, err := ssh.ParseAuthorizedKey([]byte(v)); err == nil {
										v += "  (" + ssh.FingerprintSHA256(pk) + ")"
									}
								}
								fmt.Fprintf(&b, "    %s: %s\n", f.Name, truncate(v, 2000))
							}
						}
						if len(secrets) > 0 {
							fmt.Fprintf(&b, "    secret fields (hidden): %s\n", strings.Join(secrets, ", "))
						}
					}
				}
				if n == 0 {
					return "no vault items match", nil
				}
				return b.String(), nil
			}}, nil
		},
	}
}

// vaultCall marks a vault change: always approved by the user.
func vaultCall(c *Call, scope string) *Call {
	c.Risk, c.Environment, c.Protected, c.Guarded = RiskChange, "vault", true, true
	c.Target = "vault/" + scope
	return c
}

func toolVaultImportSSHKey() Tool {
	return Tool{
		Def: llm.Tool{Name: "vault_import_ssh_key", Description: "Import an SSH private key file from THIS computer (e.g. ~/.ssh/id_ed25519) into the vault. opsdeck reads the file itself: the key never reaches you; you get its vault:// reference, type, fingerprint and public key. Then reference it from hosts (Host spec.auth) with workspace_resource. Keys protected by a passphrase must be imported by the user on the Vault page.",
			Schema: obj(map[string]any{
				"path":      str("Private key file, absolute or ~/..."),
				"name":      str("Vault item name (default: from the file name, e.g. id-ed25519)"),
				"scope":     enum("Store it in this workspace (default) or global (shared by all workspaces)", "workspace", "global"),
				"username":  str("Optional default SSH user for this key"),
				"agent_use": map[string]any{"type": "boolean", "description": "Allow the agent to use the key for connections (default true)"},
			}, "path")},
		Prepare: func(ctx context.Context, env *Env, input json.RawMessage) (*Call, error) {
			var in struct {
				Path, Name, Scope, Username string
				AgentUse                    *bool `json:"agent_use"`
			}
			if err := decode(input, &in); err != nil {
				return nil, err
			}
			lp, err := env.local()
			if err != nil {
				return nil, err
			}
			path, err := lp.Resolve(in.Path)
			if err != nil {
				return nil, err
			}
			scope, err := vaultScope(env, in.Scope)
			if err != nil {
				return nil, err
			}
			st, err := os.Stat(path)
			if err != nil {
				return nil, err
			}
			if st.Size() > 64<<10 {
				return nil, fmt.Errorf("%s is too large to be an SSH key", path)
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return nil, err
			}
			if !holdsPrivateKey(data) {
				if _, _, _, _, err := ssh.ParseAuthorizedKey(data); err == nil {
					return nil, fmt.Errorf("%s is a public key; import the private key (usually the same path without .pub)", path)
				}
				return nil, fmt.Errorf("%s does not contain an SSH private key", path)
			}
			fields, err := vault.ImportSSHKey(string(data), "")
			if err != nil {
				if strings.Contains(err.Error(), "passphrase") {
					return nil, fmt.Errorf("%s is protected by a passphrase. Ask the user to import it on the Vault page (New item → SSH key → paste or choose the file, and enter the passphrase there); never ask for the passphrase in chat", path)
				}
				return nil, fmt.Errorf("%s: %v", path, err)
			}
			pub := ""
			for _, f := range fields {
				if f.Name == "public_key" {
					pub = f.Value
				}
			}
			pk, _, _, _, _ := ssh.ParseAuthorizedKey([]byte(pub))
			fp := ""
			if pk != nil {
				fp = pk.Type() + " " + ssh.FingerprintSHA256(pk)
			}
			// Already in the vault?
			for _, sc := range []string{env.WS.Name(), vault.GlobalScope} {
				items, _ := env.Vault.List(sc)
				for _, it := range items {
					if it.Type == "ssh-key" && pub != "" && strings.HasPrefix(strings.TrimSpace(it.Get("public_key")), pub) {
						return nil, fmt.Errorf("this key (%s) is already in the vault as %s", fp, it.Ref())
					}
				}
			}
			if in.Name == "" {
				in.Name = itemName(strings.TrimSuffix(filepath.Base(path), filepath.Ext(filepath.Base(path))))
				if strings.HasPrefix(filepath.Base(path), ".") || in.Name == "" {
					in.Name = "ssh-key"
				}
			}
			if in.Username != "" {
				fields = append(fields, vault.Field{Name: "username", Value: in.Username})
			}
			agentUse := in.AgentUse == nil || *in.AgentUse
			item := vault.Item{Scope: scope, Type: "ssh-key", Name: in.Name, Fields: fields, Tags: []string{"imported"},
				Notes: agentNote("Imported from " + path), Policy: vault.Policy{AgentUse: agentUse}}
			ref := item.Ref()
			if _, _, err := env.Vault.Resolve(ref); err == nil {
				return nil, fmt.Errorf("%s already exists; choose another name", ref)
			}
			c := vaultCall(&Call{Match: "import-ssh-key " + path,
				Preview: fmt.Sprintf("Import SSH key into the vault\n\nfrom:  %s\nto:    %s\nkey:   %s\npublic key: %s\nagent use: %v\n\nThe private key goes straight into the encrypted vault; the agent never sees it.", path, ref, fp, pub, agentUse)}, scope)
			c.Run = func(ctx context.Context) (string, error) {
				it, err := env.Vault.Create(item)
				if err != nil {
					return "", err
				}
				return fmt.Sprintf("imported %s as %s\nkey: %s\npublic key: %s\nUse it on a host with spec.auth: %s", path, it.Ref(), fp, pub, it.Ref()), nil
			}
			return c, nil
		},
	}
}

func toolVaultAddItem() Tool {
	types := make([]string, 0, len(vault.Types))
	for _, t := range vault.Types {
		types = append(types, t.Type)
	}
	return Tool{
		Def: llm.Tool{Name: "vault_add_item", Description: "Create a vault item without exposing secrets to you. Non-secret fields (username, url, ...) are given in fields. Secret fields come from secrets: {\"generate\": true} creates a strong random password (or, for an ssh-key's private_key, a new ed25519 key pair whose public key you get back), or {\"file\": \"~/path\"} reads the value from a file on this computer (e.g. a kubeconfig or a WireGuard .conf). You never get secret values back. Item types: " + strings.Join(types, ", ") + ".",
			Schema: obj(map[string]any{
				"type":   enum("Item type", types...),
				"name":   str("Item name (lowercase, dashes)"),
				"scope":  enum("This workspace (default) or global", "workspace", "global"),
				"fields": map[string]any{"type": "object", "description": "Non-secret field values, e.g. {\"username\":\"deploy\",\"url\":\"https://...\"}", "additionalProperties": map[string]any{"type": "string"}},
				"secrets": map[string]any{"type": "object", "description": "Secret fields: {\"password\": {\"generate\": true, \"length\": 32}} or {\"kubeconfig\": {\"file\": \"~/.kube/config\"}}",
					"additionalProperties": map[string]any{"type": "object", "properties": map[string]any{
						"generate": map[string]any{"type": "boolean"}, "length": map[string]any{"type": "integer"},
						"symbols": map[string]any{"type": "boolean"}, "file": map[string]any{"type": "string"}}}},
				"tags":      map[string]any{"type": "array", "items": map[string]any{"type": "string"}},
				"notes":     str("Optional notes (not secret)"),
				"agent_use": map[string]any{"type": "boolean", "description": "Allow the agent to use the item (default true)"},
			}, "type", "name")},
		Prepare: func(ctx context.Context, env *Env, input json.RawMessage) (*Call, error) {
			var in struct {
				Type, Name, Scope, Notes string
				Fields                   map[string]string
				Secrets                  map[string]struct {
					Generate bool
					Length   int
					Symbols  *bool
					File     string
				}
				Tags     []string
				AgentUse *bool `json:"agent_use"`
			}
			if err := decode(input, &in); err != nil {
				return nil, err
			}
			var def *vault.TypeDef
			for i := range vault.Types {
				if vault.Types[i].Type == in.Type {
					def = &vault.Types[i]
				}
			}
			if def == nil {
				return nil, fmt.Errorf("unknown type %q", in.Type)
			}
			scope, err := vaultScope(env, in.Scope)
			if err != nil {
				return nil, err
			}
			secretField := map[string]bool{}
			for _, f := range def.Fields {
				secretField[f.Name] = f.Secret
			}
			var fields []vault.Field
			var summary []string
			names := make([]string, 0, len(in.Fields))
			for k := range in.Fields {
				names = append(names, k)
			}
			sort.Strings(names)
			for _, k := range names {
				if secretField[k] {
					return nil, fmt.Errorf("%s is a secret field: provide it in secrets (generate or file), never as a value", k)
				}
				if v := in.Fields[k]; v != "" {
					if strings.Contains(v, "PRIVATE KEY") {
						return nil, fmt.Errorf("field %s looks like a private key; use secrets with a file instead", k)
					}
					fields = append(fields, vault.Field{Name: k, Value: v})
					summary = append(summary, fmt.Sprintf("%s: %s", k, v))
				}
			}
			var run []func() error // secret producers, run after approval
			pubOut := new(string)
			snames := make([]string, 0, len(in.Secrets))
			for k := range in.Secrets {
				snames = append(snames, k)
			}
			sort.Strings(snames)
			for _, k := range snames {
				s := in.Secrets[k]
				k := k
				switch {
				case s.File != "":
					lp, err := env.local()
					if err != nil {
						return nil, err
					}
					path, err := lp.Resolve(s.File)
					if err != nil {
						return nil, err
					}
					st, err := os.Stat(path)
					if err != nil {
						return nil, err
					}
					if st.Size() > 1<<20 {
						return nil, fmt.Errorf("%s is larger than 1 MB", path)
					}
					summary = append(summary, fmt.Sprintf("%s: (secret, read from %s)", k, path))
					run = append(run, func() error {
						b, err := os.ReadFile(path)
						if err != nil {
							return err
						}
						fields = append(fields, vault.Field{Name: k, Value: string(b), Secret: true})
						return nil
					})
				case s.Generate && in.Type == "ssh-key" && k == "private_key":
					summary = append(summary, "private_key: (new ed25519 key pair generated by opsdeck)")
					run = append(run, func() error {
						kf, err := vault.GenerateSSHKey("ed25519", in.Name)
						if err != nil {
							return err
						}
						for _, f := range kf {
							if f.Name == "public_key" {
								*pubOut = f.Value
							}
						}
						fields = append(fields, kf...)
						return nil
					})
				case s.Generate:
					n := s.Length
					if n <= 0 {
						n = 32
					}
					if n < 12 || n > 256 {
						return nil, errors.New("length must be between 12 and 256")
					}
					symbols := s.Symbols == nil || *s.Symbols
					summary = append(summary, fmt.Sprintf("%s: (secret, %d random characters generated by opsdeck)", k, n))
					run = append(run, func() error {
						pw, err := vault.GeneratePassword(n, symbols)
						if err != nil {
							return err
						}
						fields = append(fields, vault.Field{Name: k, Value: pw, Secret: true})
						return nil
					})
				default:
					return nil, fmt.Errorf("secret %s: set generate or file", k)
				}
			}
			for _, f := range def.Fields {
				if f.Required {
					_, inF := in.Fields[f.Name]
					_, inS := in.Secrets[f.Name]
					if !inF && !inS {
						return nil, fmt.Errorf("%s items need %s", in.Type, f.Name)
					}
				}
			}
			agentUse := in.AgentUse == nil || *in.AgentUse
			item := vault.Item{Scope: scope, Type: in.Type, Name: in.Name, Tags: in.Tags, Policy: vault.Policy{AgentUse: agentUse}}
			item.Notes = strings.TrimSpace(in.Notes + "\n\n" + agentNote("Created"))
			if _, _, err := env.Vault.Resolve(item.Ref()); err == nil {
				return nil, fmt.Errorf("%s already exists", item.Ref())
			}
			c := vaultCall(&Call{Match: "add " + in.Type,
				Preview: fmt.Sprintf("Create vault item %s (%s)\n\n%s\nagent use: %v", item.Ref(), in.Type, strings.Join(summary, "\n"), agentUse)}, scope)
			c.Run = func(ctx context.Context) (string, error) {
				for _, f := range run {
					if err := f(); err != nil {
						return "", err
					}
				}
				item.Fields = fields
				it, err := env.Vault.Create(item)
				if err != nil {
					return "", err
				}
				out := "created " + it.Ref()
				if *pubOut != "" {
					out += "\npublic key: " + *pubOut
				}
				return out, nil
			}
			return c, nil
		},
	}
}

func toolKnownHostsImport() Tool {
	return Tool{
		Def: llm.Tool{Name: "known_hosts_import", Description: "Pin SSH host keys for workspace hosts from an OpenSSH known_hosts file on THIS computer (default ~/.ssh/known_hosts; hashed entries are supported). Hosts the user already connected to from this machine then connect with verified keys instead of trust-on-first-use. A host whose pinned key differs is reported as a conflict and left unchanged.",
			Schema: obj(map[string]any{
				"path":  str("known_hosts file (default ~/.ssh/known_hosts)"),
				"hosts": map[string]any{"type": "array", "items": map[string]any{"type": "string"}, "description": "Workspace host names or group/<name> (default: all hosts)"},
			})},
		Prepare: func(ctx context.Context, env *Env, input json.RawMessage) (*Call, error) {
			var in struct {
				Path  string
				Hosts []string
			}
			if err := decode(input, &in); err != nil {
				return nil, err
			}
			lp, err := env.local()
			if err != nil {
				return nil, err
			}
			if in.Path == "" {
				in.Path = "~/.ssh/known_hosts"
			}
			path, err := lp.Resolve(in.Path)
			if err != nil {
				return nil, err
			}
			data, err := readHead(path, 8<<20)
			if err != nil {
				return nil, err
			}
			var hosts []*workspace.Resource
			if len(in.Hosts) == 0 {
				for _, r := range env.WS.Resources {
					if r.Kind == "Host" {
						hosts = append(hosts, r)
					}
				}
			} else if hosts, err = env.hosts(strings.Join(in.Hosts, ",")); err != nil {
				return nil, err
			}
			plan := env.Hub.PlanKnownHostsImport(env.WS, hosts, data)
			var b strings.Builder
			adds := 0
			for _, p := range plan {
				fmt.Fprintf(&b, "%s (%s): %s", p.Host, p.Address, p.Status)
				switch p.Status {
				case "add":
					adds++
					fmt.Fprintf(&b, " %s", strings.Join(p.Keys, ", "))
				case "conflict":
					fmt.Fprintf(&b, " — pinned %s, file has %s (left unchanged; forget the pinned key first if the server was reinstalled)", strings.Join(p.Pinned, ", "), strings.Join(p.Keys, ", "))
				case "pinned":
					fmt.Fprintf(&b, " %s", strings.Join(p.Pinned, ", "))
				}
				b.WriteString("\n")
			}
			report := b.String()
			if report == "" {
				report = "no workspace hosts with an address\n"
			}
			if adds == 0 {
				// nothing to change: just report
				return &Call{Risk: RiskRead, Target: "local:" + path, Match: path, Environment: "local",
					Consent: "reads " + path + " on this computer", Grant: "local-read-file:" + path, GrantLabel: "Always allow reading " + path + " in this session",
					Run: func(ctx context.Context) (string, error) { return "nothing to pin\n" + report, nil }}, nil
			}
			c := &Call{Risk: RiskChange, Target: "workspace/" + env.WS.Name() + "/known_hosts", Environment: "local", Protected: true, Guarded: true, Match: path,
				Preview: "Pin host keys from " + path + "\n\n" + report}
			c.Run = func(ctx context.Context) (string, error) {
				n, err := env.Hub.ApplyKnownHostsImport(env.WS, plan)
				if err != nil {
					return "", err
				}
				return fmt.Sprintf("pinned %d key(s)\n%s", n, report), nil
			}
			return c, nil
		},
	}
}

func toolWorkspaceResource() Tool {
	return Tool{
		Def: llm.Tool{Name: "workspace_resource", Description: "Read or change the workspace inventory. action=get returns one resource as YAML; action=apply creates or replaces a resource (the full object: kind, name, environment, tags, via, description, spec); action=delete removes one. Kinds and their spec fields: Host{address, port, user, auth: vault://..., roles}, HostGroup{hosts, roles, tags}, VPN profiles WireGuard{config, mode, proxyPort}, Tailscale{controlUrl, authKey, hostname, acceptRoutes, ephemeral, proxyPort}, NetBird{managementUrl, setupKey, hostname, mode, proxyPort}, OpenVPN{config, auth, allowScripts}, OpenConnect{protocol: anyconnect|fortinet|gp|pulse|nc|f5|array, server, auth, authGroup, serverCert, cookie, mode, proxyPort}, OpenFortiVPN{server, auth, authGroup, serverCert} (mode is userspace or system), SocksProxy{address, auth}, Panel{url, ...}, GitRemote{connection: <connector id, optional: by default the connector of the URL's server>, url, branch, provider: auto|gitlab|github, token: vault://… (token or login), deployKey: vault://… (ssh-key), apiUrl, caCert (PEM), protectedBranches, docs: true to use its Markdown as documentation, docsPaths}, Database{...}, Domain{zone: example.com, connection: <DNS connector id (Cloudflare, ArvanCloud), optional: by default the connected account that has the zone>, notes}, Certificate{domains: [example.com, *.example.com], ca: letsencrypt|letsencrypt-staging|buypass|buypass-test|custom, email, keyType: ec256|ec384|rsa2048|rsa4096, renewDays, autoRenew, directoryUrl (custom)}, KubernetesCluster{...}. via is network/<name> or host/<jump>. Never put secrets in spec: use vault:// references.",
			Schema: obj(map[string]any{
				"action":   enum("Action", "get", "apply", "delete"),
				"id":       str("<kind>/<name> for get and delete"),
				"resource": map[string]any{"type": "object", "description": "For apply: the resource object"},
			}, "action")},
		Prepare: func(ctx context.Context, env *Env, input json.RawMessage) (*Call, error) {
			var in struct {
				Action, ID string
				Resource   json.RawMessage
			}
			if err := decode(input, &in); err != nil {
				return nil, err
			}
			find := func(id string) *workspace.Resource {
				kind, name, _ := strings.Cut(id, "/")
				return env.WS.Find(kind, name)
			}
			toYAML := func(r *workspace.Resource) string {
				if r == nil {
					return ""
				}
				b, _ := yaml.Marshal(r)
				return string(b)
			}
			switch in.Action {
			case "get":
				r := find(in.ID)
				if r == nil {
					return nil, fmt.Errorf("%s not found", in.ID)
				}
				return &Call{Risk: RiskRead, Target: "workspace/" + env.WS.Name(), Run: func(ctx context.Context) (string, error) { return toYAML(r), nil }}, nil
			case "delete":
				r := find(in.ID)
				if r == nil {
					return nil, fmt.Errorf("%s not found", in.ID)
				}
				return &Call{Risk: RiskDestructive, Target: "workspace/" + env.WS.Name(), Match: "delete " + r.ID(), Reasons: []string{"removes " + r.ID() + " from the inventory"},
					Preview: "Delete " + r.ID() + "\n\n" + unifiedDiff("resources", toYAML(r), ""),
					Run: func(ctx context.Context) (string, error) {
						if err := env.WS.DeleteResource(r.ID()); err != nil {
							return "", err
						}
						return "deleted " + r.ID(), nil
					}}, nil
			case "apply":
				var r workspace.Resource
				if len(in.Resource) == 0 {
					return nil, errors.New("resource is required for apply")
				}
				dec := json.NewDecoder(bytes.NewReader(in.Resource))
				if err := dec.Decode(&r); err != nil {
					return nil, fmt.Errorf("invalid resource: %v", err)
				}
				r.CleanSpec()
				if err := r.CheckNoLiteralSecrets(); err != nil {
					return nil, err
				}
				if _, ok := workspace.KindByName(r.Kind); !ok {
					return nil, fmt.Errorf("unknown kind %q", r.Kind)
				}
				for k, v := range r.Spec {
					if s, ok := v.(string); ok && strings.HasPrefix(s, "vault://") {
						if _, _, err := env.Vault.ResolveFor(env.WS.Name(), s); err != nil {
							return nil, fmt.Errorf("spec.%s: %v", k, err)
						}
					}
				}
				old := find(r.ID())
				oldID, verb := "", "Create "
				if old != nil {
					oldID, verb = old.ID(), "Update "
				}
				return &Call{Risk: RiskChange, Target: "workspace/" + env.WS.Name(), Match: "apply " + r.ID(),
					Preview: verb + r.ID() + "\n\n" + unifiedDiff(r.ID(), toYAML(old), toYAML(&r)),
					Run: func(ctx context.Context) (string, error) {
						if err := env.WS.PutResource(oldID, &r); err != nil {
							return "", err
						}
						if oldID != "" {
							// connection settings may have changed
							switch {
							case r.Kind == "Host":
								env.Hub.Disconnect(env.WS.Name(), r.Name)
							case workspace.IsNetworkKind(r.Kind):
								env.Hub.NetworkDown(env.WS.Name(), r.Name)
							}
						}
						return strings.ToLower(strings.TrimSpace(verb)) + "d " + r.ID(), nil
					}}, nil
			}
			return nil, fmt.Errorf("unknown action %q", in.Action)
		},
	}
}
